const net = require\('net'\);
const socket = new net.Socket\(\);
socket.setTimeout\(5000\);

socket.connect\(55141, 'mainline.proxy.rlwy.net', \(\) => {
  console.log\('TCP connected, sending plain startup...'\);
  // Plain startup message: user=postgres, database=railway
  const user = 'postgres';
  const db   = 'railway';
  const msg  = Buffer.alloc\(100\);
  let off = 4;
  msg.writeInt32BE\(196608, off\); off += 4; // protocol 3.0
  msg.write\('user', off\); off += 5;
  msg.write\(user, off\); off += user.length + 1;
  msg.write\('database', off\); off += 9;
  msg.write\(db, off\); off += db.length + 1;
  off++; // null terminator
  msg.writeInt32BE\(off, 0\); // total length
  socket.write\(msg.slice\(0, off\)\);
}\);

socket.on\('data', d => {
  console.log\('Response \(hex\):', d.toString\('hex'\)\);
  console.log\('Response \(ascii\):', d.toString\('ascii'\).replace\(/[^\\\\x20-\\\\x7E]/g,'?'\)\);
  socket.destroy\(\);
}\);

